#nullable enable // autogenerated

using System;
using MVZ2.Level.UI;
using PVZEngine.Tools.Unity;
using TMPro;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.Level.Starshards
{
    public class StarshardPanel : LevelUIUnit
    {
        public void SetIconSprite(Sprite? sprite)
        {
            icon.SetSprite(sprite);
        }
        public void SetSelected(bool selected)
        {
            animator.SetBool("Selected", selected);
        }
        public void SetDisabled(bool selected)
        {
            animator.SetBool("Disabled", selected);
        }
        public void SetHotkeyText(string hotkey)
        {
            if (hotkeyText)
                hotkeyText.text = hotkey;
        }
        public void SetPointCount(int maxCount)
        {
            pointsList.updateList(maxCount);
        }
        public void SetPointHighlight(int index, bool highlight)
        {
            var point = pointsList.getElement<StarshardPanelPoint>(index);
            if (point.Exists())
                point.SetHighlight(highlight);
        }
        private void Awake()
        {
            icon.OnPointerDown += (data) => OnPointerDown?.Invoke(data);
        }
        public event Action<PointerEventData>? OnPointerDown;
        public StarshardPanelIcon Icon => icon;
        [SerializeField]
        private Animator animator = null!;
        [SerializeField]
        private StarshardPanelIcon icon = null!;
        [SerializeField]
        private ElementListUI pointsList = null!;
        [SerializeField]
        private TextMeshProUGUI hotkeyText = null!;
    }
}
